import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public long nextLong() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            long res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = read();
            }
            return res;
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) return;
        long k = scanner.nextLong();

        long[] distinctVals = new long[n + 1];
        int[] counts = new int[n + 1];
        int numDistinct = 0;

        long currentPref = 0;
        distinctVals[0] = 0;
        counts[0] = 1;
        numDistinct = 1;

        for (int i = 0; i < n; i++) {
            long x = scanner.nextLong();
            currentPref += x;
            if (currentPref == distinctVals[numDistinct - 1]) {
                counts[numDistinct - 1]++;
            } else {
                distinctVals[numDistinct] = currentPref;
                counts[numDistinct] = 1;
                numDistinct++;
            }
        }

        long ans = 0;

        if (k == 0) {
            for (int i = 0; i < numDistinct; i++) {
                long c = counts[i];
                ans += c * (c - 1) / 2;
            }
        } else {
            int left = 0;
            int right = 0;
            while (right < numDistinct) {
                long diff = distinctVals[right] - distinctVals[left];
                if (diff == k) {
                    ans += (long) counts[left] * counts[right];
                    left++;
                    right++;
                } else if (diff < k) {
                    right++;
                } else {
                    left++;
                }
            }
        }

        System.out.println(ans);
    }
}
